-- Staff accounts (owner, step 9): a department for workers, and a forced password
-- change for accounts a manager creates.

-- AlterTable (generated by Prisma: migrate diff between the old and new schema)
ALTER TABLE "users" ADD COLUMN     "department" TEXT,
ADD COLUMN     "must_change_password" BOOLEAN NOT NULL DEFAULT false;

-- Not expressible in schema.prisma: a worker always has a department, and only
-- workers have one. Which departments exist is checked by the backend against
-- config/departments.json, so the list can change without a migration.
ALTER TABLE "users" ADD CONSTRAINT "users_department_only_for_workers"
  CHECK (("role" = 'worker') = ("department" IS NOT NULL));
